\paragraph{{Preliminary}}\label{subsec:difference-preliminary}
{This subsection describes several formulas for approximating derivatives $f'(x),f''(x)$ of a smooth function $f(x)$ at $x$ using $f(x),f(x-h)$, and $f(x+h)$ with $0<h<1$. Consider how to approximate $f'(x)$. The Taylor series of $f(x)$ is given by}
\begin{equation}\label{eq:taylor-difference-expansion}
f(x+h)=f(x)+f'(x)h+\frac{1}{2!}f''(x)h^2+\frac{1}{3!}f'''(x)h^3+\cdots.
\end{equation}
{Then, $f'(x)$ is written as}
\[\begin{aligned}
f'(x)&=\frac{f(x+h)-f(x)}{h}-\frac{1}{2!}f''(x)h-\frac{1}{3!}f'''(x)h^2-\cdots\\
&=\frac{f(x+h)-f(x)}{h}+O(h).
\end{aligned}\]

{$O(\cdot)$ is the big O notation. Roughly speaking, $O(h)$ in this case means that $-\frac{1}{2!}f''(x)h-\frac{1}{3!}f'''(x)h^2-\cdots$ can be written as $ch$ for a suitable constant value $c$ as $h\to0$. The approximation to $f'(x)$ by the recurrence}
\begin{equation}\label{eq:forward-difference}
f'(x)\approx\frac{f(x+h)-f(x)}{h}
\end{equation}
{is referred to as the forward difference. The accuracy of the forward difference is of order $h$. A similar approximation}
\begin{equation}\label{eq:backward-difference}
f'(x)\approx\frac{f(x)-f(x-h)}{h}
\end{equation}
{is referred to as the backward difference. The accuracy of the backward difference is also of order $h$. For a more accurate formula, it follows from \eqref{eq:taylor-difference-expansion} that we have}
\[\frac{f(x+h)-f(x-h)}{2h}=f'(x)+O(h^2),\]
{from which, we have}
\begin{equation}\label{eq:central-first-difference}
f'(x)\approx\frac{f(x+h)-f(x-h)}{2h},
\end{equation}
{and this is referred to as the central difference for the first derivative of $f(x)$, whose accuracy is of order $h^2$.}

{We now consider approximating the second derivative $f''(x)$. From the Taylor series \eqref{eq:taylor-difference-expansion} of $f(x+h)$ and $f(x-h)$, we have}
\[f(x+h)-2f(x)+f(x-h)=f''(x)h^2+O(h^4).\]
{Thus}
\[f''(x)=\frac{f(x+h)-2f(x)+f(x-h)}{h^2}+O(h^2).\]
{The following approximation}
\begin{equation}\label{eq:central-second-difference}
f''(x)\approx\frac{f(x+h)-2f(x)+f(x-h)}{h^2}
\end{equation}
{is referred to as the central difference for the second derivative of $f(x)$, whose accuracy is of order $h^2$.}

\refstepcounter{applicationexample}
\paragraph{Example~\theapplicationexample\space({Symmetric Matrix})}\label{subsec:laplace-difference}
\begingroup\makeatletter\edef\@currentlabel{\theapplicationexample}\label{ex:laplace-difference}\makeatother\endgroup
{Consider the Laplace equation of the form}
\[\begin{aligned}
u_{xx}+u_{yy}&=0,&(x,y)&\in(0,1)\times(0,1),\\
u(x,y)&=g(x,y),&(x,y)&\in\Gamma,
\end{aligned}\]
{where $\Gamma$ is the boundary of $(0,1)\times(0,1)$. To be specific, the boundary condition is given by $u(0,y)=g(0,y)$, $u(1,y)=g(1,y)$, $u(x,0)=g(x,0)$, and $u(x,1)=g(x,1)$.}
{We now approximately solve the Laplace equation by using central difference \eqref{eq:central-second-difference}. To this end, an equispaced grid of $N\times N$ points in $(0,1)\times(0,1)$ is used. The case $N=3$ ($h=1/4$) is shown in Fig.\ \ref{fig:laplace-grid}.}

\begin{figure}[htbp]\centering
\includegraphics[width=.48\linewidth]{figures/laplace-grid.png}
\caption{{Mesh grid on the region for example\ \ref{ex:laplace-difference} (the Laplace equation)}}\label{fig:laplace-grid}
\end{figure}

{In the following, we use the mesh in Fig.\ \ref{fig:laplace-grid} and we will see how linear systems are obtained. Central difference \eqref{eq:central-second-difference} for approximating $u_{xx}$ and $u_{yy}$ is given by}
\begin{equation}\label{eq:laplace-xx-discretization}
u_{xx}(x,y)\approx\frac{1}{h^2}(u(x+h,y)-2u(x,y)+u(x-h,y)),
\end{equation}
\begin{equation}\label{eq:laplace-yy-discretization}
u_{yy}(x,y)\approx\frac{1}{h^2}(u(x,y+h)-2u(x,y)+u(x,y-h)).
\end{equation}
{It is convenient to introduce an abbreviated notation $u_{i,j}=u(x_i,y_j)$. Then we obtain the following five-point formula:}
\begin{equation}\label{eq:laplace-five-point}
u_{xx}(x_i,y_j)+u_{yy}(x_i,y_j)\approx\frac{1}{h^2}(u_{i+1,j}+u_{i-1,j}-4u_{i,j}+u_{i,j+1}+u_{i,j-1}),
\end{equation}
{where $u(x_i,y_j)=g(x_i,y_j)$ on the boundary. Let $u_1:=u(x_1,y_1)$, $u_2:=u(x_1,y_2)$,\ldots, $u_9:=u(x_3,y_3)$ and $g_{i,j}:=u(x_i,y_j)$ on the boundary. Then from Fig.\ \ref{fig:laplace-grid} and \eqref{eq:laplace-five-point}, unknowns $u_1,u_2,\ldots,u_9$ have the following relations:}
\[\begin{aligned}
u_2+g_{0,1}-4u_1+u_4+g_{1,0}&=0,\\
u_3+u_1-4u_2+u_5+g_{2,0}&=0,\\
g_{4,1}+u_2-4u_3+u_6+g_{3,0}&=0,\\
u_5+g_{0,2}-4u_4+u_7+u_1&=0,\\
&\vdots\\
g_{4,3}+u_8-4u_9+g_{3,4}+u_6&=0.
\end{aligned}\]

{The corresponding matrix form is}
\begin{equation}\label{eq:laplace-grid-system}
\underbrace{\left[\begin{array}{rrr|rrr|rrr}
-4&1&0&1&0&0&0&0&0\\1&-4&1&0&1&0&0&0&0\\0&1&-4&0&0&1&0&0&0\\\hline
1&0&0&-4&1&0&1&0&0\\0&1&0&1&-4&1&0&1&0\\0&0&1&0&1&-4&0&0&1\\\hline
0&0&0&1&0&0&-4&1&0\\0&0&0&0&1&0&1&-4&1\\0&0&0&0&0&1&0&1&-4
\end{array}\right]}_A
\underbrace{\begin{bmatrix}u_1\\u_2\\u_3\\u_4\\u_5\\u_6\\u_7\\u_8\\u_9\end{bmatrix}}_{\boldsymbol{x}}
=\underbrace{-\begin{bmatrix}g_{1,0}\\g_{2,0}\\g_{3,0}\\0\\0\\0\\0\\0\\0\end{bmatrix}
-\begin{bmatrix}0\\0\\0\\0\\0\\0\\g_{1,4}\\g_{2,4}\\g_{3,4}\end{bmatrix}
-\begin{bmatrix}g_{0,1}\\0\\0\\g_{0,2}\\0\\0\\g_{0,3}\\0\\0\end{bmatrix}
-\begin{bmatrix}0\\0\\g_{4,1}\\0\\0\\g_{4,2}\\0\\0\\g_{4,3}\end{bmatrix}}_{\boldsymbol{b}}.
\end{equation}
{By solving the linear systems, we obtain the approximate solution $u_1,\ldots,u_9$ on the mesh grid.}

{The matrix of the linear systems \eqref{eq:laplace-grid-system} has a special nonzero structure, which can be rewritten in a simple form using Kronecker product. Let $A(=\{a_{ij}\})$ and $B$ are matrices. Then, the symbol $A\otimes B$ is called the Kronecker product (or Tensor product), defined by}
\begin{equation}\label{eq:kronecker-product-definition}
A\otimes B:=\begin{bmatrix}a_{11}B&\cdots&a_{1m}B\\\vdots&\ddots&\vdots\\a_{n1}B&\cdots&a_{nm}B\end{bmatrix}.
\end{equation}
{Below is an example for $A,B$ being 2-by-2 matrices:}
\[A\otimes B=\left[\begin{array}{c|c}a_{11}B&a_{12}B\\\hline a_{21}B&a_{22}B\end{array}\right]
=\left[\begin{array}{cc|cc}
a_{11}b_{11}&a_{11}b_{12}&a_{12}b_{11}&a_{12}b_{12}\\
a_{11}b_{21}&a_{11}b_{22}&a_{12}b_{21}&a_{12}b_{22}\\\hline
a_{21}b_{11}&a_{21}b_{12}&a_{22}b_{11}&a_{22}b_{12}\\
a_{21}b_{21}&a_{21}b_{22}&a_{22}b_{21}&a_{22}b_{22}
\end{array}\right].\]
{Now, let}
\[M=\begin{bmatrix}-2&1&0\\1&-2&1\\0&1&-2\end{bmatrix},\quad I=\begin{bmatrix}1&0&0\\0&1&0\\0&0&1\end{bmatrix}.\]
{Then, the coefficient matrix $A$ in \eqref{eq:laplace-grid-system} can be written as}
\begin{equation}\label{eq:laplace-kronecker-sum}
A=I\otimes M+M\otimes I.
\end{equation}
{The size of the matrix $A$ is $3^2\times3^2$. In general, $N\times N$ grid yields an $N^2\times N^2$ matrix, which can be very large and symmetric. Krylov subspace methods for symmetric linear systems are described in Sect.\ \ref{sec:hermitian-linear-systems}. Finally, some properties of the Kronecker product are listed below.}

\begin{Theorem}\label{thm:kronecker-product-properties}
{The Kronecker product has the following properties:}
\begin{enumerate}
\item {For $A\in\mathbb{C}^{m\times n},B\in\mathbb{C}^{p\times q},C\in\mathbb{C}^{r\times s}$,}
\[(A\otimes B)\otimes C=A\otimes(B\otimes C).\]
\item {For $A,B\in\mathbb{C}^{m\times n},C\in\mathbb{C}^{p\times q}$,}
\[(A+B)\otimes C=A\otimes C+B\otimes C.\]
\item {For $A\in\mathbb{C}^{m\times n},B,C\in\mathbb{C}^{p\times q}$,}
\[A\otimes(B+C)=A\otimes B+A\otimes C.\]
\item {For $c\in\mathbb{C},A\in\mathbb{C}^{m\times n},B\in\mathbb{C}^{p\times q}$,}
\[(cA)\otimes B=A\otimes(cB)=c(A\otimes B).\]
\item {For $A\in\mathbb{C}^{m\times n},B\in\mathbb{C}^{p\times q}$,}
\[(A\otimes B)^{\mathrm H}=A^{\mathrm H}\otimes B^{\mathrm H}.\]
\item {For $A\in\mathbb{C}^{m\times n},B\in\mathbb{C}^{p\times q},C\in\mathbb{C}^{n\times r},D\in\mathbb{C}^{q\times s}$,}
\[(A\otimes B)(C\otimes D)=(AC)\otimes(BD).\]
\end{enumerate}
\end{Theorem}

\begin{Proof}
{We only give a proof of (6). The $(i,k)$ block element of $A\otimes B$ is $a_{i,k}B$, and the $(k,j)$ block element of $C\otimes D$ is $c_{k,j}D$. Thus the $(i,j)$ block element of $(A\otimes B)(C\otimes D)$ is given as}
\[\begin{aligned}
((A\otimes B)(C\otimes D))_{i,j}&=\sum_{k=1}^n(a_{i,k}B)(c_{k,j}D)=\left(\sum_{k=1}^na_{i,k}c_{k,j}\right)BD\\
&=(AC)_{i,j}BD=((AC)\otimes(BD))_{i,j},
\end{aligned}\]
{which concludes the proof.}
\end{Proof}

{Note that $(i,j)$ ``block'' element is not a scalar but a matrix. For example, consider the following 2-by-2 block matrices of the form}
\[A=\begin{bmatrix}A_{11}&A_{12}\\A_{21}&A_{22}\end{bmatrix},\quad B=\begin{bmatrix}B_{11}&B_{12}\\B_{21}&B_{22}\end{bmatrix}.\]
{Then the $(1,1)$ block element of $A$ is matrix $A_{11}$, and the $(1,2)$ block element of $B$ is matrix $B_{12}$. Furthermore, we can calculate $AB$ as if the submatrices $A_{i,j}$ and $B_{i,j}$ are scalars when the matrix multiplication $A_{i,j}B_{j,k}$ is defined. For example, The $(1,1)$ block element of $AB$ is given by $A_{11}B_{11}+A_{12}B_{21}$. From Theorem\ \ref{thm:kronecker-product-properties}-(6), the following properties hold true.}

\begin{Corollary}\label{cor:kronecker-inverse}
{Let $A$ and $B$ be invertible matrices. Then}
\[(A\otimes B)^{-1}=A^{-1}\otimes B^{-1}.\]
\end{Corollary}

\begin{Proof}
{From Theorem\ \ref{thm:kronecker-product-properties}-(6), we have $(A^{-1}\otimes B^{-1})(A\otimes B)=(A^{-1}A)\otimes(B^{-1}B)=I\otimes I$, which is the Kronecker product of the two identity matrices. It is easy to see that the Kronecker product of the identity matrices is the identity matrix.}
\end{Proof}

\begin{Corollary}\label{cor:kronecker-eigenpairs}
{Let $\boldsymbol{p}_i^{(A)}$ and $\boldsymbol{p}_j^{(B)}$ be eigenvectors of $A$ and $B$, and the corresponding eigenvalues are $\lambda_i^{(A)}$ and $\lambda_j^{(B)}$. Then an eigenvector of $A\otimes B$ is $\boldsymbol{p}_i^{(A)}\otimes\boldsymbol{p}_j^{(B)}$, and the corresponding eigenvalue is $\lambda_i^{(A)}\lambda_j^{(B)}$, i.e.,}
\[(A\otimes B)\left(\boldsymbol{p}_i^{(A)}\otimes\boldsymbol{p}_j^{(B)}\right)=\lambda_i^{(A)}\lambda_j^{(B)}\left(\boldsymbol{p}_i^{(A)}\otimes\boldsymbol{p}_j^{(B)}\right).\]
\end{Corollary}

\begin{Proof}
{From Theorem\ \ref{thm:kronecker-product-properties}-(4) and (6), we have}
\[(A\otimes B)\left(\boldsymbol{p}_i^{(A)}\otimes\boldsymbol{p}_j^{(B)}\right)=\left(A\boldsymbol{p}_i^{(A)}\right)\otimes\left(B\boldsymbol{p}_j^{(B)}\right)=\lambda_i\lambda_j\left(\boldsymbol{p}_i^{(A)}\otimes\boldsymbol{p}_j^{(B)}\right),\]
{which concludes the proof.}
\end{Proof}

\begin{Corollary}\label{cor:kronecker-sum-eigenpairs}
{Using the same notations as in Corollary\ \ref{cor:kronecker-eigenpairs}, it follows that}
\[(A\otimes I+I\otimes B)\left(\boldsymbol{p}_i^{(A)}\otimes\boldsymbol{p}_j^{(B)}\right)=\left(\lambda_i^{(A)}+\lambda_j^{(B)}\right)\left(\boldsymbol{p}_i^{(A)}\otimes\boldsymbol{p}_j^{(B)}\right),\]
{where $I$ is the identity matrix.}
\end{Corollary}

{The matrix $A\otimes I+I\otimes B$ is referred to as a Kronecker sum (or Tensor sum). It follows from Corollary\ \ref{cor:kronecker-sum-eigenpairs} that eigenvectors and eigenvalues of matrix $A$ in \eqref{eq:laplace-kronecker-sum} can be given by $(\boldsymbol{p}_i\otimes\boldsymbol{p}_j,\lambda_i+\lambda_j)$, where $\boldsymbol{p}_i$ and $\lambda_i$ are the $i$th eigenvector and eigenvalue of $M$. This indicates that matrix $A$ in \eqref{eq:laplace-kronecker-sum} is not invertible if and only if there exist $i,j$ such that $\lambda_i=-\lambda_j$. Thus, the distribution of eigenvalues of much smaller matrices $M$ than $A$ determines whether matrix $A$ is invertible or not.}
{In general, Kronecker product does not commute, i.e.,}
\[A\otimes B\ne B\otimes A,\]
{where $A\in\mathbb{C}^{m\times n}$, $B\in\mathbb{C}^{p\times q}$. However, there are permutation matrices $P_{mp}\in\mathbb{R}^{mp\times mp}$ and $P_{nq}\in\mathbb{R}^{nq\times nq}$ such that}
\[P_{mp}^{\top}(A\otimes B)P_{nq}=B\otimes A.\]
{We describe this fact in detail as given next.}

\begin{Theorem}\label{thm:kronecker-permutation}
{Let $P_{mn}\in\mathbb{R}^{mn\times mn}$ be a matrix of the form}
\begin{equation}\label{eq:kronecker-commutation-matrix}
P_{mn}=\begin{bmatrix}
(E_{11})^{\top}&(E_{12})^{\top}&\cdots&(E_{1n})^{\top}\\
(E_{21})^{\top}&(E_{22})^{\top}&\cdots&(E_{2n})^{\top}\\
\vdots&\vdots&\ddots&\vdots\\
(E_{m1})^{\top}&(E_{m2})^{\top}&\cdots&(E_{mn})^{\top}
\end{bmatrix},
\end{equation}
{where $E_{i,j}\in\mathbb{R}^{m\times n}$ is a matrix whose $(i,j)$ element is one and the other elements are zeros. Then,}
\[P_{mn}=P_{nm}^{\top}=P_{nm}^{-1}\]
{and for $A\in\mathbb{C}^{m\times n},B\in\mathbb{C}^{p\times q}$,}
\begin{equation}\label{eq:kronecker-swapping-permutation}
\underbrace{P_{mp}^{\top}}_{mp\times mp}\underbrace{(A\otimes B)}_{mp\times nq}\underbrace{P_{nq}}_{nq\times nq}=B\otimes A.
\end{equation}
{If $A$ and $B$ are square matrices (i.e., $m=n$, $p=q$),}
\[P_{mp}^{\top}(A\otimes B)P_{mp}=B\otimes A.\]
\end{Theorem}

\begin{Proof}
{We give a proof of \eqref{eq:kronecker-swapping-permutation}. The $(i,j)$ block element of $P_{m,n}$ in \eqref{eq:kronecker-commutation-matrix} is $E_{ij}^{\top}$, and $E_{ij}$ can be factorized as}
\[E_{ij}=\boldsymbol{e}_i\boldsymbol{e}_j^{\top},\]
{where $\boldsymbol{e}_i$ is the $i$th unit vector, i.e., the $i$th element is one, and the others are zeros. Let $a_{ij}$ and $b_{ij}$ be the $(i,j)$ elements of $A$ and $B$. Then, from \eqref{eq:kronecker-commutation-matrix}, the $(i,j)$ block element of $P_{mp}^{\top}(A\otimes B)P_{nq}$ is calculated as}
\[\begin{aligned}
\left(P_{mp}^{\top}(A\otimes B)P_{nq}\right)_{ij}
&=\sum_{k,\ell}E_{ki}(a_{k\ell}B)E_{\ell j}^{\top}=\sum_{k,\ell}a_{k\ell}\left(E_{ki}BE_{j\ell}\right)\\
&=\sum_{k,\ell}a_{k\ell}\left(\boldsymbol{e}_k\boldsymbol{e}_i^{\top}B\boldsymbol{e}_j\boldsymbol{e}_\ell^{\top}\right)
=\sum_{k,\ell}a_{k\ell}\left(\boldsymbol{e}_kb_{ij}\boldsymbol{e}_\ell^{\top}\right)\\
&=b_{ij}\sum_{k,\ell}a_{k\ell}\left(\boldsymbol{e}_k\boldsymbol{e}_\ell^{\top}\right)
=b_{ij}\left(\sum_{k,\ell}a_{k\ell}E_{k\ell}\right)=b_{ij}A\\
&=(B\otimes A)_{ij},
\end{aligned}\]
{which concludes the proof.}
\end{Proof}

\refstepcounter{applicationexample}
\paragraph{Example~\theapplicationexample\space({Complex Symmetric Matrix})}\label{subsec:helmholtz-difference}
\begingroup\makeatletter\edef\@currentlabel{\theapplicationexample}\label{ex:helmholtz-difference}\makeatother\endgroup
{We consider the following boundary value problem:}
\[\begin{aligned}
u_{xx}+u_{yy}+\sigma^2u&=0,&(x,y)&\in(0,\pi)\times(0,\pi),\\
u_x|_{x=0}&=i\sqrt{\sigma^2-\tfrac14}\cos\tfrac y2,&&\text{Neumann Condition (1)},\\
u_x|_{x=\pi}-i\sqrt{\sigma^2-\tfrac14}u|_{x=\pi}&=0,&&\text{Radiation Condition},\\
u_y|_{y=0}&=0,&&\text{Neumann Condition (2)},\\
u|_{y=\pi}&=0,&&\text{Dirichlet Condition},
\end{aligned}\]
{The elliptic partial differential equation is known as the Helmholtz equation, see, e.g., \BookCite{19}. For simplicity, we use a 3-by-3 mesh grid as shown in Figs.\ \ref{fig:helmholtz-grid} and \ref{fig:helmholtz-ghost-grid}. Similar to Example\ \ref{ex:laplace-difference} in the previous section, applying \eqref{eq:laplace-xx-discretization}--\eqref{eq:laplace-five-point} to the Helmholtz equation yields}
\begin{equation}\label{eq:helmholtz-five-point}
-u_{i+1,j}-u_{i-1,j}+(4-h^2\sigma^2)u_{i,j}-u_{i,j+1}-u_{i,j-1}=0.
\end{equation}
{Considering Eq.\ \eqref{eq:helmholtz-five-point} over the mesh points given in Fig.\ \ref{fig:helmholtz-ghost-grid} leads to the following six equations:}

\begin{figure}[htbp]\centering
\includegraphics[width=.48\linewidth]{figures/helmholtz-grid.png}
\caption{{Mesh points on the region}}\label{fig:helmholtz-grid}
\end{figure}

\begin{figure}[htbp]\centering
\includegraphics[width=.48\linewidth]{figures/helmholtz-ghost-grid.png}
\caption{{Mesh points on the region satisfying the boundary conditions}}\label{fig:helmholtz-ghost-grid}
\end{figure}

\begin{equation}\label{eq:helmholtz-six-equations}
\left\{\begin{aligned}
-u_2-g_4-u_4-g_1+(4-h^2\sigma^2)u_1&=0,\\
-u_3-u_1-u_5-g_2+(4-h^2\sigma^2)u_2&=0,\\
-g_5-u_2-u_6-g_3+(4-h^2\sigma^2)u_3&=0,\\
-u_5-g_6-g_8-u_1+(4-h^2\sigma^2)u_4&=0,\\
-u_6-u_4-g_9-u_2+(4-h^2\sigma^2)u_5&=0,\\
-g_7-u_5-g_{10}-u_3+(4-h^2\sigma^2)u_3&=0,
\end{aligned}\right.
\end{equation}
{where $u_1:=u_{1,1}=u(0,0)$, $u_2:=u_{2,1}=u(h,0)$, $u_3:=u_{3,1}=u(2h,0)$, $u_4:=u_{1,2}=u(0,h)$, $u_5:=u_{2,2}=u(h,h)$, $u_6:=u_{3,2}=u(2h,h)$ and $h=\pi/2$. Here $g_k$'s for $k=1,\ldots,10$ in Fig.\ \ref{fig:helmholtz-ghost-grid} can be computed by considering the four boundary conditions as follows: first, from Neumann Condition (2) it follows that}
\[\frac{u_4-g_1}{2h}=\frac{u_5-g_2}{2h}=\frac{u_6-g_3}{2h}=0,\]
{and thus}
\[g_1=u_4,\quad g_2=u_5,\quad g_3=u_6.\]
{Second, from Neumann Condition (1), we have}

\[u_x(0,0)\approx\frac{u_2-g_4}{2h}=id\cos\left(\frac02\right),\quad
u_x(0,h)\approx\frac{u_5-g_6}{2h}=id\cos\left(\frac12\times\frac h2\right).\]
{or equivalently,}
\[g_4=u_2-2idh,\quad g_6=u_5-2idh\cos\left(\frac h4\right),\]
{where $d=\sqrt{\sigma^2-1/4}$. Third, from the Radiation Condition we obtain}
\[\frac{g_5-u_2}{2h}-idu_3=\frac{g_7-u_5}{2h}-idu_6=0\]
{or equivalently,}
\[g_5=u_2+2idhu_3,\quad g_7=u_5+2idhu_6.\]
{Finally, it follows from the Dirichlet Condition that $g_8,g_9$ and $g_{10}$ satisfy}
\[g_8=g_9=g_{10}=0.\]

{Substituting $g_1,g_2,\ldots,g_{10}$ into the six equations \eqref{eq:helmholtz-six-equations} yields the following linear systems:}
\begin{equation}\label{eq:helmholtz-unscaled-system}
\begin{bmatrix}
a&-2&0&-2&0&0\\-1&a&-1&0&-2&0\\0&-2&a-idh&0&0&-2\\
-1&0&0&a&-2&0\\0&-1&0&-1&a&-1\\0&0&-1&0&-2&a-idh
\end{bmatrix}
\begin{bmatrix}u_1\\u_2\\u_3\\u_4\\u_5\\u_6\end{bmatrix}
=\begin{bmatrix}f_1\\0\\0\\f_4\\0\\0\end{bmatrix},
\end{equation}
{where $a=\sqrt{\sigma^2-1/4}$, $f_1=-2idh$, and $f_4=-2idh\cos(h/4)$. The coefficient matrix of the linear systems \eqref{eq:helmholtz-unscaled-system} is not symmetric. By scaling each equation, we obtain symmetric linear systems of the form}
\begin{equation}\label{eq:helmholtz-symmetric-system}
\begin{bmatrix}
a/4&-1/2&0&-1/2&0&0\\-1/2&a/2&-1/2&0&-1&0\\0&-1/2&(a-idh)/4&0&0&-1/2\\
-1/2&0&0&a/2&-1&0\\0&-1&0&-1&a&-1\\0&0&-1/2&0&-1&(a-idh)/2
\end{bmatrix}
\begin{bmatrix}u_1\\u_2\\u_3\\u_4\\u_5\\u_6\end{bmatrix}
=\begin{bmatrix}f_1/4\\0\\0\\f_4/2\\0\\0\end{bmatrix}.
\end{equation}
{The coefficient matrix of the form \eqref{eq:helmholtz-symmetric-system} is non-Hermitian but symmetric, i.e., complex symmetric. Krylov subspace methods for solving complex symmetric linear systems are described in Sect.\ \ref{sec:complex-symmetric-linear-systems}.}

\refstepcounter{applicationexample}
\paragraph{Example~\theapplicationexample\space({Nonsymmetric Matrix})}\label{subsec:nonsymmetric-difference}
\begingroup\makeatletter\edef\@currentlabel{\theapplicationexample}\label{ex:nonsymmetric-difference}\makeatother\endgroup
{Consider the following three-dimensional partial differential equation:}
\[\begin{aligned}
[\boldsymbol{a}\cdot(\nabla*\nabla)+\boldsymbol{b}\cdot\nabla+c]u(x,y,z)&=g(x,y,z),&&\text{in }\Omega,\\
u(x,y,z)&=0,&&\text{on }\partial\Omega.
\end{aligned}\]
{Here, $\Omega$ is the cubic domain, i.e., $(0,1)\times(0,1)\times(0,1)$ and $\partial\Omega$ is the boundary. The symbol ``$*$'' denotes element-wise multiplication. Equivalently, the operator $\boldsymbol{a}\cdot(\nabla*\nabla)+\boldsymbol{b}\cdot\nabla+c$ is rewritten as}
\[a_1\frac{\partial^2}{\partial x^2}+a_2\frac{\partial^2}{\partial y^2}+a_3\frac{\partial^2}{\partial z^2}+b_1\frac{\partial}{\partial x}+b_2\frac{\partial}{\partial y}+b_3\frac{\partial}{\partial z}+c\]
{with $\boldsymbol{a}=[a_1,a_2,a_3]^{\top}$, $\boldsymbol{b}=[b_1,b_2,b_3]^{\top}$ and $\boldsymbol{c}=[c_1,c_2,c_3]^{\top}$. Using central difference \eqref{eq:central-second-difference} for the second derivative of $u$ yields}
\[\begin{aligned}
a_1u_{xx}(x,y,z)&\approx\frac{a_1}{h^2}(u(x+h,y,z)-2u(x,y,z)+u(x-h,y,z)),\\
a_2u_{yy}(x,y,z)&\approx\frac{a_2}{h^2}(u(x,y+h,z)-2u(x,y,z)+u(x,y-h,z)),\\
a_3u_{zz}(x,y,z)&\approx\frac{a_3}{h^2}(u(x,y,z+h)-2u(x,y,z)+u(x,y,z-h)).
\end{aligned}\]
{Similarly, using central difference \eqref{eq:central-first-difference} for the first derivative of $u$ gives}
\[\begin{aligned}
b_1u_x(x,y,z)&\approx\frac{b_1}{2h}(u(x+h,y,z)-u(x-h,y,z)),\\
b_2u_y(x,y,z)&\approx\frac{b_2}{2h}(u(x,y+h,z)-u(x,y-h,z)),\\
b_3u_z(x,y,z)&\approx\frac{b_3}{2h}(u(x,y,z+h)-u(x,y,z-h)).
\end{aligned}\]

{Considering an $(N+1)\times(N+1)\times(N+1)$ grid, together with the central differences above, leads to}
\[\begin{aligned}
&[\boldsymbol{a}\cdot(\nabla*\nabla)+\boldsymbol{b}\cdot\nabla+c]u(x,y,z)\\
&\quad\approx\frac{a_1}{h^2}(u_{i+1,j,k}-2u_{i,j,k}+u_{i-1,j,k})+\frac{b_1}{2h}(u_{i+1,j,k}-u_{i-1,j,k})+cu_{i,j,k}\\
&\qquad+\frac{a_2}{h^2}(u_{i,j+1,k}-2u_{i,j,k}+u_{i,j-1,k})+\frac{b_2}{2h}(u_{i,j+1,k}-u_{i,j-1,k})\\
&\qquad+\frac{a_3}{h^2}(u_{i,j,k+1}-2u_{i,j,k}+u_{i,j,k-1})+\frac{b_3}{2h}(u_{i,j,k+1}-u_{i,j,k-1}),
\end{aligned}\]
{where $h=1/(N+1)$. Since $u=0$ on the boundary, following Sect.\ \ref{subsec:laplace-difference}, we obtain}
\begin{equation}\label{eq:three-dimensional-difference-system}
(I_N\otimes I_N\otimes A+I_N\otimes B\otimes I_N+C\otimes I_N\otimes I_N)\boldsymbol{u}=\boldsymbol{g},
\end{equation}
{where $I_N$ is the $N$-by-$N$ identity matrix, each element of $\boldsymbol{u}$ and $\boldsymbol{g}$ corresponds to $u(x_i,y_i,z_i)$ and $g(x_i,y_i,z_i)$, and}
\[\begin{aligned}
A&:=\frac{a_1}{h^2}M_1+\frac{b_1}{2h}M_2+cI_N,\\
B&:=\frac{a_2}{h^2}M_1+\frac{b_2}{2h}M_2,\\
C&:=\frac{a_3}{h^2}M_1+\frac{b_3}{2h}M_2.
\end{aligned}\]
{Here, $M_1$ and $M_2$ are defined by}
\[M_1:=\begin{bmatrix}-2&1&&&\\1&-2&1&&\\&\ddots&\ddots&\ddots&\\&&1&-2&1\\&&&1&-2\end{bmatrix},\quad
M_2:=\begin{bmatrix}0&1&&&\\-1&0&1&&\\&\ddots&\ddots&\ddots&\\&&-1&0&1\\&&&-1&0\end{bmatrix}.\]
{$M_1$ and $M_2$ are $N$-by-$N$ (tridiagonal Toeplitz) matrices, and blanks in the matrices are zeros.}

